/**
 * A semente do dente-de-leão — porte de `componentes/viz/dente_leao.js`.
 *
 * O "papo" (pappus) não é um paraquedas: é uma coroa de cerdas rala o bastante
 * para o ar ATRAVESSAR. Na porosidade certa — cerca de 90% de vazio — o ar que
 * passa forma um anel de vórtice estável logo acima da semente, e é ele que
 * multiplica o arrasto. Denso demais, o ar não passa; ralo demais, ele escapa
 * sem enrolar. Nos dois casos o vórtice some e a semente cai.
 *
 * Por isso a cena mostra o vórtice, e não só a semente: é o vórtice que decide.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  rodape,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** A porosidade em que o vórtice fecha, quando o módulo não diz outra. */
const ALVO_PADRAO = 91;

const denteLeao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const porosidade = Math.max(0, numeroDe(valores, 'p', 0));
    const ok = info.ok === true;
    const alvo = numeroDe(info, 'alvo', ALVO_PADRAO);

    titulo(ctx, L, A, ok ? 'O vórtice se formou — ela voa' : 'Sem vórtice, ela cai');

    // Escala da figura pela altura útil, para o papo não estourar o topo.
    const S = limitar(A / 300, 0.75, 1.4);

    // Voando: sobe e deriva ao vento. Caindo: desce em ciclo.
    const altura = ok ? 0.46 + Math.sin(t * 1.1) * 0.05 : 0.42 + ((t * 0.45) % 1) * 0.38;
    const derivaX = ok ? Math.sin(t * 0.65) * L * 0.1 : 0;
    const cx = L * 0.5 + derivaX;
    const cy = A * altura;

    const coroaY = cy - 26 * S;
    const cerda = 30 * S;
    const vortY = coroaY - 18 * S;

    // O chão, de onde a semente tem de escapar.
    ctx.strokeStyle = cor.trilho;
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(0, A * 0.88);
    ctx.lineTo(L, A * 0.88);
    ctx.stroke();
    ctx.setLineDash([]);

    // O anel de vórtice: forte no alvo, some conforme se afasta dele.
    const forca = ok ? 1 : Math.max(0, 1 - Math.abs(porosidade - alvo) / 30);
    if (forca > 0.05) {
      ctx.strokeStyle = cor.azulClaro;
      ctx.globalAlpha = 0.65 * forca;
      ctx.lineWidth = 2.5;
      for (let i = 0; i < 2; i++) {
        const raio = (22 + i * 8) * S + Math.sin(t * 2) * 3;
        ctx.beginPath();
        ctx.ellipse(cx, vortY, raio, raio * 0.45, 0, 0, Math.PI * 2);
        ctx.stroke();
      }

      // As setas dizem que o anel CIRCULA — sem elas ele lê como dois riscos.
      ctx.fillStyle = cor.azulClaro;
      ctx.globalAlpha = 0.85 * forca;
      for (const lado of [-1, 1]) {
        const ax = cx + lado * 30 * S;
        ctx.beginPath();
        ctx.moveTo(ax, vortY - 7);
        ctx.lineTo(ax + lado * 9, vortY);
        ctx.lineTo(ax, vortY + 7);
        ctx.closePath();
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    // O papo. Menos porosidade = mais cerdas, e é isso que fecha a passagem do ar.
    const cerdas = Math.round(10 + (100 - porosidade) * 0.5);
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.3;
    for (let i = 0; i < cerdas; i++) {
      const angulo = (i / cerdas) * Math.PI - Math.PI;
      const x2 = cx + Math.cos(angulo) * cerda;
      const y2 = coroaY + Math.sin(angulo) * cerda;

      ctx.beginPath();
      ctx.moveTo(cx, coroaY);
      ctx.lineTo(x2, y2);
      ctx.stroke();

      ctx.fillStyle = cor.trilho;
      ctx.beginPath();
      ctx.arc(x2, y2, 2.4, 0, Math.PI * 2);
      ctx.fill();
    }

    // Haste e semente.
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(cx, coroaY);
    ctx.lineTo(cx, cy);
    ctx.stroke();

    ctx.fillStyle = MATERIAIS.madeira;
    ctx.beginPath();
    ctx.ellipse(cx, cy + 6 * S, 3 * S, 7 * S, 0, 0, Math.PI * 2);
    ctx.fill();

    etiqueta(
      ctx,
      `porosidade ${Math.round(porosidade)}%`,
      L / 2,
      A * 0.8,
      limitar(A * 0.04, 9, 13),
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Vórtice estável: ela plana e voa longe ✔',
      'Sem vórtice: ela cai — ajuste a porosidade.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default denteLeao;
